<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';
import PmsMyWorkAssignees from './PmsMyWorkAssignees.vue';
import {descriptionHtml} from './description';
import PmsDescriptionEditor from './PmsDescriptionEditor.vue';
import PmsSubtaskDetail from './PmsSubtaskDetail.vue';
import PmsSubmissions from './PmsSubmissions.vue';
import {ref,onMounted,onUnmounted,computed} from 'vue';
const props=defineProps<{id:number;csrf?:string;permissions:string[];initialAction?:string}>();const emit=defineEmits(['close','updated']);const collaborator=ref(''),assigneeSearch=ref(''),editOptions=ref<any>(null);const invitation=ref<any>(null),inviteLink=ref('');const placement=ref<any>(null),placementProjects=ref<any[]>([]);const selectedSubtask=ref<number|null>(null);const assignees=ref<any[]|null>(null),assignedIds=ref<number[]>([]),estimate=ref<number|null>(null);const handoff=ref<any>(null),handoffOptions=ref<any[]>([]);const subtaskTitle=ref(''),subtaskEditor=ref<any>(null);const task=ref<any>(null),editor=ref<any>(null),error=ref(''),busy=ref(false),comment=ref(''),files=ref<File[]>([]);const estimatePercent=computed(()=>task.value?.original_estimate_minutes?Math.round((task.value.time_tracking?.total_seconds||0)/(task.value.original_estimate_minutes*60)*100):0);const estimateColor=computed(()=>estimatePercent.value>100?'danger':estimatePercent.value>=80?'warning':'success');function duration(minutes:number){return Math.floor(minutes/60)+'h '+minutes%60+'m';}const taskImages=computed(()=>{const raw=task.value?.images;if(Array.isArray(raw))return raw;try{return JSON.parse(raw||'[]');}catch{return [];}});const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);
async function api(path:string,method='GET',body?:any){const form=body instanceof FormData;const r=await fetch('/pms/api/'+path,{method,headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf||'',...(form?{}:{'Content-Type':'application/json'})},body:body?(form?body:JSON.stringify(body)):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message);return d;}
function closeAction(kind:string){if(kind==='edit')editor.value=null;else if(kind==='assign')assignees.value=null;else if(kind==='handoff')handoff.value=null;else if(kind==='place')placement.value=null;if(props.initialAction===kind)emit('close');}
async function openPlacement(){await run(async()=>{placementProjects.value=(await api('tasks/'+props.id+'/placement-options')).projects;placement.value={project_id:'',sprint_id:''};});}
async function place(){await run(async()=>{const result=await api('tasks/'+props.id+'/place','POST',placement.value);window.location.assign(result.redirect_url);});}
async function subtaskStatus(s:any,e:Event){await run(async()=>{const result=await api('subtask-status','POST',{sub_task_id:s.id,status:(e.target as HTMLSelectElement).value});if(result.success===false)throw Error(result.message);});}
async function taskField(field:string,value:any){await run(async()=>{await api('task-'+(field==='due_date'?'due-date':field),'POST',{task_id:props.id,[field]:value});});}
async function taskStatus(e:Event){await run(async()=>{const d=await api('task-status','POST',{task_id:props.id,status:(e.target as HTMLSelectElement).value});if(d.success===false)throw Error(d.message);});}
async function approval(e:Event){await run(async()=>{await api('task-approval','POST',{task_id:props.id,approval:(e.target as HTMLSelectElement).value});});}
async function openAssignees(){await run(async()=>{assignees.value=(await api('tasks/'+props.id+'/assignees')).users;assignedIds.value=task.value.users.map((u:any)=>u.id);});}
async function saveAssignees(){await run(async()=>{await api('tasks/'+props.id+'/board','PATCH',{assignee_ids:assignedIds.value});assignees.value=null;});}
async function saveEstimate(){await run(async()=>{await api('tasks/'+props.id+'/board','PATCH',{original_estimate_minutes:estimate.value});estimate.value=null;});}
async function openHandoff(){await run(async()=>{handoffOptions.value=(await api('tasks/'+props.id+'/handoff')).departments;handoff.value={destination_department_id:'',destination_project_id:'',notes:''};});}
async function sendHandoff(){await run(async()=>{const result=await api('tasks/'+props.id+'/handoff','POST',handoff.value);window.location.assign(result.redirect_url);});}
async function addSubtask(){await run(async()=>{await api('subtasks','POST',{task_id:props.id,title:subtaskTitle.value});subtaskTitle.value='';});}
async function saveSubtask(){await run(async()=>{await api('subtasks/'+subtaskEditor.value.id,'PUT',{title:subtaskEditor.value.title});subtaskEditor.value=null;});}
async function inviteExisting(){await run(async()=>{await api('invitations','POST',{recipient_id:Number(collaborator.value),invitable_type:'task',invitable_id:props.id,role:'task_assignee'});collaborator.value='';});}
async function invite(){await run(async()=>{const d=await api('tasks/'+props.id+'/invite','POST',invitation.value);inviteLink.value=d.invitation_url||d.invitation?.url||d.url||'';invitation.value=null;});}
async function deleteTask(){if(!confirm('Delete this task and its subtasks?'))return;busy.value=true;try{await api('tasks/'+props.id,'DELETE');emit('updated');emit('close');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function load(){task.value=(await api('tasks/'+props.id)).task;}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();await load();emit('updated');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function edit(){await run(async()=>{const t=task.value;if(t.project_id)editOptions.value=(await api('projects/'+t.project_id+'?workflow='+(t.workflow_id||''))).data;else editOptions.value=(await api('team-space/'+t.department_id)).data;editor.value={title:t.title,description:t.description||'',due_date:t.due_date?.slice(0,16)||null,priority:t.priority,workflow_id:t.workflow_id,workflow_column_id:t.workflow_column_id,sprint_id:t.sprint_id,assignee_ids:t.users.map((u:any)=>u.id),original_estimate_minutes:t.original_estimate_minutes};});}
async function save(){await run(async()=>{const payload={...editor.value};if(!can('task-status')){delete payload.workflow_column_id;delete payload.workflow_id;}if(!can('task-assign'))delete payload.assignee_ids;if(!payload.original_estimate_minutes||payload.original_estimate_minutes===task.value.original_estimate_minutes)delete payload.original_estimate_minutes;await api('tasks/'+props.id+'/board','PATCH',payload);closeAction('edit');});}
async function addComment(){await run(async()=>{await api('tasks/'+props.id+'/comments','POST',{body:comment.value});comment.value='';});}
async function upload(){await run(async()=>{const f=new FormData();files.value.forEach(file=>f.append('attachments[]',file));await api('tasks/'+props.id+'/attachments','POST',f);files.value=[];});}
async function remove(kind:string,id:number){if(confirm('Delete this '+kind+'?'))await run(async()=>{await api(kind+'s/'+id,'DELETE');});}
async function timer(action:string){await run(async()=>{await api('timers/'+action,'POST',{task_id:props.id});});}
function liveUpdate(){if(!busy.value&&!editor.value)void load().catch(e=>error.value=(e as Error).message);}onMounted(()=>{void run(load).then(async()=>{if(props.initialAction==='edit')edit();else if(props.initialAction==='assign')await openAssignees();else if(props.initialAction==='handoff')await openHandoff();else if(props.initialAction==='place')await openPlacement();else if(props.initialAction==='delete'){await deleteTask();emit('close');}});window.addEventListener('pms:changed',liveUpdate);});onUnmounted(()=>window.removeEventListener('pms:changed',liveUpdate));
</script>
<template><div class="pms-form-backdrop" :style="initialAction&&!error?{background:'transparent'}:undefined" @click.self="emit('close')"><section v-show="!initialAction||error" class="pms-task-modal pms-source-issue-details" role="dialog" aria-modal="true" aria-label="Issue details"><header class="pms-task-modal-header"><div><small class="work-key">{{(task?.project?.name||task?.department?.dept_name||'TSK').slice(0,3).toUpperCase()}}-{{id}}</small><div class="d-flex align-items-center gap-2"><h5>{{task?.title||'Issue details'}}</h5><span v-if="task" class="badge bg-label-info"><i class="fa" :class="['fa-arrow-down','fa-equals','fa-arrow-up','fa-angles-up'][task.priority??1]"></i> {{['Low','Normal','High','Urgent'][task.priority??1]}} priority</span></div></div><button class="btn btn-sm btn-label-secondary pms-project-issue-close" aria-label="Close" @click="emit('close')"><i class="ti ti-x" aria-hidden="true"></i></button></header><p v-if="error" class="notice admin-error">{{error}}</p><div v-if="busy" class="pms-task-loading" role="status"><span class="spinner-border spinner-border-sm" aria-hidden="true"></span><span class="visually-hidden">Loading issue...</span></div><div v-if="task" class="pms-task-modal-body"><div class="pms-task-main"><div class="pms-description mb-4" v-if="task.description" v-html="descriptionHtml(task.description)"></div><p v-else class="text-muted mb-4">No description provided.</p><div class="pms-time-panel"><div><small>TIME TRACKING</small><h3>{{task.time_tracking?.formatted||'0s'}} logged</h3></div><div v-if="task.directly_assigned_to_me" class="editor-actions"><button v-if="!task.own_running_timer&&task.status!=='completed'" class="button primary" :disabled="busy" @click="timer('start')"><i aria-hidden="true" class="ti ti-player-play"></i>Start timer</button><template v-if="task.own_running_timer"><button class="button" :disabled="busy" @click="timer('pause')">Pause timer</button><button class="button" :disabled="busy" @click="timer('stop')"><i aria-hidden="true" class="ti ti-player-stop"></i>Stop timer</button></template></div><div v-for="u in task.time_tracking?.by_user" :key="u.user_id" class="d-flex justify-content-between py-1"><span>{{u.name}}</span><strong>{{u.formatted}}</strong></div><div class="pms-issue-estimate"><span>Original estimate</span><strong :class="'text-'+estimateColor">{{task.original_estimate_minutes?duration(task.original_estimate_minutes)+' ('+estimatePercent+'%)':'Not set'}}</strong><div v-if="task.original_estimate_minutes" class="progress w-100 mt-2" style="height:7px"><div class="progress-bar" :class="'bg-'+estimateColor" :style="{width:Math.min(estimatePercent,100)+'%'}"></div></div></div></div><div class="d-flex justify-content-between mt-4 mb-2"><h6>Subtasks</h6><small class="text-muted">{{task.subtasks.filter((s:any)=>s.status==='completed').length}}/{{task.subtasks.length}} complete</small></div><div class="pms-task-sublist"><article v-for="s in task.subtasks" :key="s.id" class="list-group-item d-flex justify-content-between align-items-center"><div><i class="fa me-2" :class="s.status==='completed'?'fa-circle-check text-success':'fa-circle text-muted'"></i><button class="pms-subtask-title" @click="selectedSubtask=s.id">{{s.title}}</button><span class="badge bg-label-secondary ms-2">{{s.status.replaceAll('_',' ')}}</span></div><button v-if="can('sub-task-trash')" class="btn btn-sm btn-icon text-danger" aria-label="Delete subtask" :disabled="busy" @click="remove('subtask',s.id)"><i class="fa fa-trash"></i></button></article><p v-if="!task.subtasks.length" class="muted">No subtasks yet.</p></div><form v-if="can('sub-task-add')" class="editor-actions" @submit.prevent="addSubtask"><input v-model="subtaskTitle" required maxlength="255" placeholder="Add a subtask" aria-label="Subtask title"><button class="button primary" :disabled="busy||!subtaskTitle.trim()">Add</button></form><hr class="my-4"><div class="d-flex justify-content-between mt-4 mb-2"><h6>Attachments</h6><small class="text-muted">{{task.attachments.length}} file(s)</small></div><div class="editor-actions"><a v-for="url in taskImages" :key="url" :href="url" target="_blank" rel="noopener"><img :src="url" alt="Task attachment" style="max-width:180px;max-height:120px;object-fit:contain"></a></div><div class="pms-task-sublist"><article v-for="a in task.attachments" :key="a.id"><a :href="a.url||('/storage/'+a.path)" target="_blank" rel="noopener"><i aria-hidden="true" class="ti ti-paperclip"></i>{{a.original_name}}</a><button class="button" :disabled="busy" @click="remove('attachment',a.id)">Delete</button></article><p v-if="!task.attachments.length" class="muted">No attachments yet.</p></div><form @submit.prevent="upload"><div class="form-text mb-1"><i class="fa fa-circle-info me-1"></i>PDF, Office, CSV, TXT, JPG, PNG, WebP, GIF or ZIP &#183; Up to 10 files, 10 MB each.</div><div class="input-group"><input class="form-control" aria-label="Add files" type="file" multiple accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.csv,.txt,.jpg,.jpeg,.png,.webp,.gif,.zip" @change="files=Array.from(($event.target as HTMLInputElement).files||[])"><button class="btn btn-outline-primary" :disabled="busy||!files.length">Upload</button></div></form><details class="pms-issue-controls mt-4"><summary>Issue actions</summary><div class="editor-actions"><span class="pms-status-badge">{{task.workflow_column?.name||task.status}}</span><span class="pms-status-badge"><i class="fa" :class="['fa-arrow-down','fa-equals','fa-arrow-up','fa-angles-up'][task.priority??1]"></i> {{['Low','Normal','High','Urgent'][task.priority??1]}} priority</span><span class="muted">Due {{task.due_date||'not set'}}</span></div><label v-if="can('task-status')">Task status<select :value="task.status" :disabled="busy" @change="taskStatus"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="in_review">In review</option><option value="completed">Completed</option></select></label><label v-if="task.can_manage_approvals">Approval<select :value="task.approval" :disabled="busy" @change="approval"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></label><p class="muted">{{task.approval_note}}</p><label v-if="can('task-priority')">Priority<select :value="task.priority" :disabled="busy" @change="taskField('priority',Number(($event.target as HTMLSelectElement).value))"><option v-for="(label,index) in ['Low','Normal','High','Urgent']" :key="index" :value="index">{{label}}</option></select></label><label v-if="can('task-due-date')">Due date<input type="datetime-local" :value="task.due_date?.slice(0,16)" :disabled="busy" @change="taskField('due_date',($event.target as HTMLInputElement).value)"></label><form v-if="can('description-update')&&!can('task-edit')" @submit.prevent="taskField('description',task.description)"><label>Description<PmsDescriptionEditor v-model="task.description"/></label><button class="button" :disabled="busy">Save description</button></form><p class="muted">Assigned to: {{task.users?.map((u:any)=>u.name).join(', ')||'Unassigned'}}</p><button v-if="can('task-assign')" class="button" :disabled="busy" @click="openAssignees">Manage assignees</button><button v-if="can('task-edit')&&!editor" class="button" @click="edit"><i aria-hidden="true" class="ti ti-edit"></i>Edit task</button><button v-if="can('task-handoff')" class="button" :disabled="busy" @click="openHandoff">Hand off to department</button><button v-if="!task.project_id&&task.department_id&&can('task-edit')&&can('task-handoff')" class="button" :disabled="busy" @click="openPlacement">Place into project</button><form v-if="assignees&&can('project-assign')" @submit.prevent="inviteExisting"><label>Invite existing employee<select v-model="collaborator" required><option disabled value="">Select employee</option><option v-for="u in assignees" :key="u.id" :value="u.id">{{u.name}}</option></select></label><button class="button" :disabled="busy">Send invitation</button></form><button v-if="can('task-assign')&&task.project_id" class="button" @click="invitation={email:'',name:'',delivery_method:'email'}">Invite task assignee</button><p v-if="inviteLink"><a :href="inviteLink">Open invitation</a></p><details v-if="task.estimate_histories?.length"><summary>Estimate history</summary><p v-for="h in task.estimate_histories" :key="h.id">{{h.user?.name||'Administrator'}}: {{h.old_minutes||0}} to {{h.new_minutes}} minutes &middot; {{new Date(h.created_at).toLocaleString()}}</p></details><PmsSubmissions type="task" :id="id" :csrf="csrf" :can-submit="task.directly_assigned_to_me"/></details></div><aside class="pms-task-comments"><header><strong><i aria-hidden="true" class="ti ti-messages"></i> Comments</strong><span class="pms-status-badge">{{task.comments.length}}</span><small>Issue conversation</small></header><div class="pms-comment-list issue-comments-list"><article v-for="c in [...task.comments].reverse()" :key="c.id" class="issue-comment" :class="{'own-comment':c.user_id===task.viewer_id}"><img class="issue-comment-avatar" :src="c.user?.profile_img||'/pms-assets/assets/img/user-picture.png'" alt=""><div class="issue-comment-content"><div class="issue-comment-meta"><span class="issue-comment-name">{{c.user?.name||c.author_name||'Administrator'}}</span><span>{{new Date(c.created_at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}}</span></div><div class="issue-comment-bubble">{{c.body}}<button v-if="permissions.includes('*')||c.user_id===task.viewer_id" class="btn btn-sm btn-icon issue-comment-delete" :disabled="busy" aria-label="Delete comment" @click="remove('comment',c.id)"><i class="fa fa-trash"></i></button></div></div></article><div v-if="!task.comments.length" class="jira-empty"><i class="fa fa-comments d-block mb-2 fs-4"></i>No comments yet.<br><small>Start the conversation below.</small></div></div><form @submit.prevent="addComment"><textarea v-model="comment" required rows="2" maxlength="5000" aria-label="Comment" placeholder="Write a comment..." @keydown.ctrl.enter.prevent="comment.trim()&&!busy&&addComment()"></textarea><div class="d-flex justify-content-between align-items-center mt-2"><small class="text-muted">Ctrl + Enter to send</small><button class="button primary" :disabled="busy||!comment.trim()"><i class="ti ti-send"></i>Send</button></div></form></aside></div><footer class="pms-task-modal-footer pms-issue-extra-footer"><button v-if="can('task-trash')" class="button" :disabled="busy" @click="deleteTask">Delete task</button><a v-if="task?.project_id" class="button" :href="'/pms?section=project-board&project='+task.project_id">Open project board</a><button class="button primary" @click="emit('close')">Close</button></footer></section><PmsMyWorkAssignees v-if="assignees" :task="task" :users="assignees" :csrf="csrf" @close="closeAction('assign')" @updated="load();emit('updated')"/><PmsFormDialog v-if="editor" title="Edit task" wide @close="closeAction('edit')"><form class="pms-reference-form" @submit.prevent="save"><label class="full-width">Title<input v-model="editor.title" required maxlength="255"></label><label class="full-width">Description<PmsDescriptionEditor v-model="editor.description"/></label><label>Workflow column<select v-model="editor.workflow_column_id" :disabled="!can('task-status')"><option v-for="c in editOptions?.selectedWorkflow?.columns" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Priority<select v-model.number="editor.priority"><option :value="0">Low</option><option :value="1">Normal</option><option :value="2">High</option><option :value="3">Urgent</option></select></label><label>Due date<input type="datetime-local" v-model="editor.due_date"></label><label>Sprint<select v-model="editor.sprint_id"><option :value="null">Backlog</option><option v-for="sp in editOptions?.sprints" :key="sp.id" :value="sp.id">{{sp.name}}</option></select></label><label class="full-width">Assignees<select v-model="editor.assignee_ids" multiple size="5" :disabled="!can('task-assign')"><option v-for="u in editOptions?.asignee" :key="u.id" :value="u.id">{{u.name}}</option></select><small>Select everyone who will work on this task. Clear all selections to unassign everyone.</small></label><label class="full-width">Original estimate (hours)<input type="number" :value="editor.original_estimate_minutes?editor.original_estimate_minutes/60:''" min="0.25" max="8760" step="0.25" placeholder="Example: 8" @input="editor.original_estimate_minutes=Number(($event.target as HTMLInputElement).value)*60"><small>Warning at 80%; red when logged time exceeds this estimate.</small></label><div class="editor-actions"><button type="button" class="button" @click="closeAction('edit')">Cancel</button><button class="button primary" :disabled="busy">Save changes</button></div></form></PmsFormDialog><PmsFormDialog v-if="handoff" title="Hand off task" centered @close="closeAction('handoff')"><form  class="pms-reference-form" @submit.prevent="sendHandoff"><label class="full-width">Destination department<select v-model="handoff.destination_department_id" required @change="handoff.destination_project_id=''"><option disabled value="">Select department</option><option v-for="d in handoffOptions" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="full-width">Destination project<select v-model="handoff.destination_project_id"><option value="">Department backlog</option><option v-for="p in handoffOptions.find((d:any)=>d.id===handoff.destination_department_id)?.projects||[]" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label class="full-width">Handoff instructions<textarea v-model="handoff.notes" maxlength="5000"></textarea></label><div class="editor-actions"><button class="button primary" :disabled="busy">Complete and hand off</button><button type="button" class="button" @click="closeAction('handoff')">Cancel</button></div></form></PmsFormDialog><PmsFormDialog v-if="placement" title="Place task in project" centered @close="closeAction('place')"><form  class="pms-reference-form" @submit.prevent="place"><label class="full-width">Project<select v-model="placement.project_id" required @change="placement.sprint_id=''"><option disabled value="">Select approved project</option><option v-for="p in placementProjects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label class="full-width">Sprint<select v-model="placement.sprint_id"><option value="">Project backlog</option><option v-for="s in placementProjects.find((p:any)=>p.id===placement.project_id)?.sprints||[]" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="editor-actions"><button class="button primary" :disabled="busy">Place task</button><button type="button" class="button" @click="closeAction('place')">Cancel</button></div></form></PmsFormDialog><PmsFormDialog v-if="invitation" title="Invite task assignee" centered @close="invitation=null"><form  @submit.prevent="invite"><label class="full-width">Email<input type="email" v-model="invitation.email" required></label><label class="full-width">Name<input v-model="invitation.name"></label><label class="full-width">Delivery<select v-model="invitation.delivery_method"><option value="email">Email</option><option value="manual">Manual link</option></select></label><button class="button primary" :disabled="busy">Create invitation</button></form></PmsFormDialog><PmsFormDialog v-if="subtaskEditor" title="Edit subtask" centered @close="subtaskEditor=null"><form  class="pms-reference-form" @submit.prevent="saveSubtask"><input v-model="subtaskEditor.title" required maxlength="255" aria-label="Edit subtask title"><button class="button primary" :disabled="busy">Save</button><button type="button" class="button" @click="subtaskEditor=null">Cancel</button></form></PmsFormDialog><PmsSubtaskDetail v-if="selectedSubtask" :id="selectedSubtask" :task-id="id" :csrf="csrf" :permissions="permissions" @close="selectedSubtask=null" @updated="load"/></div></template>